use base64::{engine::general_purpose::STANDARD as BASE64,Engine as _};
use ring::{aead,rand::{SecureRandom,SystemRandom}};use serde::{Deserialize,Serialize};use sha2::{Digest,Sha256};use std::{fs,io::Write,path::{Path,PathBuf}};use thiserror::Error;use crate::local_health_vault::{LocalHealthVaultCrypto,LocalHealthVaultRecord};
const NONCE_LEN:usize=12;const KEY_LEN:usize=32;const INDEX_SCHEMA_VERSION:&str="1.0.0";
pub trait VaultKeyProvider{fn key_for(&self,key_ref:&str)->Result<[u8;KEY_LEN],StorageError>;}pub trait VaultAuthorizer{fn authorize(&self,context:&AuthorizationContext,record_id:&str,action:VaultAction)->bool;}
#[derive(Debug,Clone,PartialEq,Eq)]pub struct AuthorizationContext{pub principal_ref:String,pub subject_ref:String,pub scope:String}
#[derive(Debug,Clone,Copy,PartialEq,Eq)]pub enum VaultAction{Write,Read,List,Tombstone,Verify}
#[derive(Debug,Error,PartialEq,Eq)]pub enum StorageError{#[error("authorization denied")]AuthorizationDenied,#[error("record not found")]NotFound,#[error("record is tombstoned")]Tombstoned,#[error("invalid storage record")]InvalidRecord,#[error("index integrity failure")]IndexIntegrityFailure,#[error("record integrity failure")]RecordIntegrityFailure,#[error("key resolution failed")]KeyResolutionFailed,#[error("storage I/O failure")]Io,#[error("serialization failure")]Serialization,#[error("random nonce generation failed")]NonceGenerationFailed}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)]struct EncryptedIndex{schema_version:String,record_id:String,key_ref:String,nonce:String,ciphertext:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)]struct IndexPlaintext{record_id:String,subject_ref:String,entity_type:String,schema_version:String,classification:String,content_type:String,key_ref:String,provenance_ref:String,created_at:String,updated_at:String,record_state:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)]struct StoredBundle{record:LocalHealthVaultRecord,index:EncryptedIndex}
#[derive(Debug,Clone,PartialEq,Eq)]pub struct AuthorizedIndexEntry{pub record_id:String,pub subject_ref:String,pub entity_type:String,pub schema_version:String,pub classification:String,pub content_type:String,pub key_ref:String,pub provenance_ref:String,pub created_at:String,pub updated_at:String,pub record_state:String}
pub struct LocalFileVaultStore<K,A>{root:PathBuf,key_provider:K,authorizer:A}
impl<K,A>LocalFileVaultStore<K,A>where K:VaultKeyProvider,A:VaultAuthorizer{pub fn new(root:impl AsRef<Path>,key_provider:K,authorizer:A)->Result<Self,StorageError>{fs::create_dir_all(root.as_ref()).map_err(|_|StorageError::Io)?;Ok(Self{root:root.as_ref().to_path_buf(),key_provider,authorizer})}pub fn put(&self,record:LocalHealthVaultRecord,context:&AuthorizationContext)->Result<(),StorageError>{if !self.authorizer.authorize(context,&record.record_id,VaultAction::Write)||context.subject_ref!=record.subject_ref||record.tombstone{return Err(StorageError::AuthorizationDenied)}let key=self.key_provider.key_for(&record.key_ref).map_err(|_|StorageError::KeyResolutionFailed)?;LocalHealthVaultCrypto::decrypt_record(&key,&record).map_err(|_|StorageError::RecordIntegrityFailure)?;let index=IndexPlaintext{record_id:record.record_id.clone(),subject_ref:record.subject_ref.clone(),entity_type:record.entity_type.clone(),schema_version:record.schema_version.clone(),classification:record.classification.clone(),content_type:record.content_type.clone(),key_ref:record.key_ref.clone(),provenance_ref:record.provenance_ref.clone(),created_at:record.created_at.clone(),updated_at:record.updated_at.clone(),record_state:"ACTIVE".into()};let bundle=StoredBundle{record,index:encrypt_index(&key,&index)?};let bytes=serde_json::to_vec(&bundle).map_err(|_|StorageError::Serialization)?;atomic_write(&self.path_for(&bundle.record.subject_ref,&bundle.record.record_id),&bytes)}pub fn get(&self,record_id:&str,context:&AuthorizationContext)->Result<LocalHealthVaultRecord,StorageError>{if !self.authorizer.authorize(context,record_id,VaultAction::Read){return Err(StorageError::AuthorizationDenied)}let bundle=self.load(&context.subject_ref,record_id)?;if bundle.record.subject_ref!=context.subject_ref{return Err(StorageError::AuthorizationDenied)}let key=self.key_provider.key_for(&bundle.record.key_ref).map_err(|_|StorageError::KeyResolutionFailed)?;let index=decrypt_index(&key,&bundle.index)?;validate_binding(&bundle,&index)?;if index.record_state=="TOMBSTONED"||bundle.record.tombstone{return Err(StorageError::Tombstoned)}LocalHealthVaultCrypto::decrypt_record(&key,&bundle.record).map_err(|_|StorageError::RecordIntegrityFailure)?;Ok(bundle.record)}pub fn list(&self,context:&AuthorizationContext)->Result<Vec<AuthorizedIndexEntry>,StorageError>{if !self.authorizer.authorize(context,"*",VaultAction::List){return Err(StorageError::AuthorizationDenied)}let subject_dir=self.subject_path(&context.subject_ref);let mut entries=Vec::new();let directory=match fs::read_dir(subject_dir){Ok(d)=>d,Err(e)if e.kind()==std::io::ErrorKind::NotFound=>return Ok(entries),Err(_)=>return Err(StorageError::Io)};for item in directory{let path=item.map_err(|_|StorageError::Io)?.path();if !path.is_file()||path.extension().and_then(|v|v.to_str())!=Some("bundle"){continue}let bundle:StoredBundle=serde_json::from_slice(&fs::read(&path).map_err(|_|StorageError::Io)?).map_err(|_|StorageError::InvalidRecord)?;let key=self.key_provider.key_for(&bundle.record.key_ref).map_err(|_|StorageError::KeyResolutionFailed)?;let index=decrypt_index(&key,&bundle.index)?;validate_binding(&bundle,&index)?;if index.subject_ref==context.subject_ref&&self.authorizer.authorize(context,&index.record_id,VaultAction::Read){entries.push(index.into())}}Ok(entries)}pub fn tombstone(&self,record_id:&str,context:&AuthorizationContext)->Result<(),StorageError>{if !self.authorizer.authorize(context,record_id,VaultAction::Tombstone){return Err(StorageError::AuthorizationDenied)}let mut bundle=self.load(&context.subject_ref,record_id)?;let key=self.key_provider.key_for(&bundle.record.key_ref).map_err(|_|StorageError::KeyResolutionFailed)?;let mut index=decrypt_index(&key,&bundle.index)?;validate_binding(&bundle,&index)?;if index.subject_ref!=context.subject_ref{return Err(StorageError::AuthorizationDenied)}bundle.record.tombstone=true;index.record_state="TOMBSTONED".into();bundle.index=encrypt_index(&key,&index)?;let bytes=serde_json::to_vec(&bundle).map_err(|_|StorageError::Serialization)?;atomic_write(&self.path_for(&context.subject_ref,record_id),&bytes)}pub fn verify(&self,record_id:&str,context:&AuthorizationContext)->Result<(),StorageError>{if !self.authorizer.authorize(context,record_id,VaultAction::Verify){return Err(StorageError::AuthorizationDenied)}let bundle=self.load(&context.subject_ref,record_id)?;let key=self.key_provider.key_for(&bundle.record.key_ref).map_err(|_|StorageError::KeyResolutionFailed)?;let index=decrypt_index(&key,&bundle.index)?;validate_binding(&bundle,&index)?;if !bundle.record.tombstone{LocalHealthVaultCrypto::decrypt_record(&key,&bundle.record).map_err(|_|StorageError::RecordIntegrityFailure)?}Ok(())}fn load(&self,subject_ref:&str,record_id:&str)->Result<StoredBundle,StorageError>{let bytes=fs::read(self.path_for(subject_ref,record_id)).map_err(|e|if e.kind()==std::io::ErrorKind::NotFound{StorageError::NotFound}else{StorageError::Io})?;serde_json::from_slice(&bytes).map_err(|_|StorageError::InvalidRecord)}fn subject_path(&self,subject_ref:&str)->PathBuf{let subject_hash=hex::encode(Sha256::digest(subject_ref.as_bytes()));self.root.join(subject_hash)}fn path_for(&self,subject_ref:&str,record_id:&str)->PathBuf{let record_hash=hex::encode(Sha256::digest(record_id.as_bytes()));self.subject_path(subject_ref).join(format!("{record_hash}.bundle"))}}
fn validate_binding(bundle:&StoredBundle,index:&IndexPlaintext)->Result<(),StorageError>{if index.record_id!=bundle.record.record_id||index.subject_ref!=bundle.record.subject_ref||index.key_ref!=bundle.record.key_ref||index.classification!=bundle.record.classification||index.provenance_ref!=bundle.record.provenance_ref{return Err(StorageError::IndexIntegrityFailure)}Ok(())}
fn encrypt_index(key:&[u8;KEY_LEN],index:&IndexPlaintext)->Result<EncryptedIndex,StorageError>{let aad=format!("soma-index-v1:{}:{}",index.record_id,index.key_ref);let sealing=aead::LessSafeKey::new(aead::UnboundKey::new(&aead::AES_256_GCM,key).map_err(|_|StorageError::KeyResolutionFailed)?);let mut nonce_bytes=[0u8;NONCE_LEN];SystemRandom::new().fill(&mut nonce_bytes).map_err(|_|StorageError::NonceGenerationFailed)?;let nonce=aead::Nonce::assume_unique_for_key(nonce_bytes);let mut plaintext=serde_json::to_vec(index).map_err(|_|StorageError::Serialization)?;sealing.seal_in_place_append_tag(nonce,aead::Aad::from(aad.as_bytes()),&mut plaintext).map_err(|_|StorageError::Serialization)?;Ok(EncryptedIndex{schema_version:INDEX_SCHEMA_VERSION.into(),record_id:index.record_id.clone(),key_ref:index.key_ref.clone(),nonce:BASE64.encode(nonce_bytes),ciphertext:BASE64.encode(plaintext)})}
fn decrypt_index(key:&[u8;KEY_LEN],encrypted:&EncryptedIndex)->Result<IndexPlaintext,StorageError>{if encrypted.schema_version!=INDEX_SCHEMA_VERSION{return Err(StorageError::InvalidRecord)}let nonce_vec=BASE64.decode(&encrypted.nonce).map_err(|_|StorageError::IndexIntegrityFailure)?;if nonce_vec.len()!=NONCE_LEN{return Err(StorageError::IndexIntegrityFailure)}let nonce=aead::Nonce::try_assume_unique_for_key(&nonce_vec).map_err(|_|StorageError::IndexIntegrityFailure)?;let mut ciphertext=BASE64.decode(&encrypted.ciphertext).map_err(|_|StorageError::IndexIntegrityFailure)?;let aad=format!("soma-index-v1:{}:{}",encrypted.record_id,encrypted.key_ref);let opening=aead::LessSafeKey::new(aead::UnboundKey::new(&aead::AES_256_GCM,key).map_err(|_|StorageError::KeyResolutionFailed)?);let plaintext=opening.open_in_place(nonce,aead::Aad::from(aad.as_bytes()),&mut ciphertext).map_err(|_|StorageError::IndexIntegrityFailure)?;let index:IndexPlaintext=serde_json::from_slice(plaintext).map_err(|_|StorageError::IndexIntegrityFailure)?;if index.record_id!=encrypted.record_id||index.key_ref!=encrypted.key_ref{return Err(StorageError::IndexIntegrityFailure)}Ok(index)}
fn atomic_write(path:&Path,bytes:&[u8])->Result<(),StorageError>{if let Some(parent)=path.parent(){fs::create_dir_all(parent).map_err(|_|StorageError::Io)?}let tmp=path.with_extension(format!("bundle.tmp-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map_err(|_|StorageError::Io)?.as_nanos()));let mut file=fs::File::create(&tmp).map_err(|_|StorageError::Io)?;if file.write_all(bytes).is_err()||file.sync_all().is_err(){let _=fs::remove_file(&tmp);return Err(StorageError::Io)}if fs::rename(&tmp,path).is_err(){let _=fs::remove_file(&tmp);return Err(StorageError::Io)}Ok(())}
impl From<IndexPlaintext> for AuthorizedIndexEntry{fn from(v:IndexPlaintext)->Self{Self{record_id:v.record_id,subject_ref:v.subject_ref,entity_type:v.entity_type,schema_version:v.schema_version,classification:v.classification,content_type:v.content_type,key_ref:v.key_ref,provenance_ref:v.provenance_ref,created_at:v.created_at,updated_at:v.updated_at,record_state:v.record_state}}}
